from pathlib import Path
import json
base = Path('products/distribution/catalogue-referral')
for name in ('item-4-operator-decision-pointer.json', 'item-4-release-binding.json'):
    path = base / name
    if path.is_file():
        print(json.dumps({'artifact': str(path), 'record': json.loads(path.read_text())}, ensure_ascii=False))
    else:
        print(json.dumps({'artifact': str(path), 'available_in_selected_inputs': False}))
